1	import { useQuery } from '@tanstack/react-query';
2	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
3	import type { ContentfulClientApi } from 'contentful';
4	import { useContentfulClient } from './useContentfulClient';
5	import { filterByRegion, pickMostSpecificByRegion } from '../utils/resolveByRegion';
6	import { CONTENT_TYPE_IDS } from '../config/contentfulMapping';
7	import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
8	import type { HeaderNavigationEntry, HeaderNavItemEntry } from '../types/contentful';
9	
10	// Contentful resolves nested references `include` levels deep, and the header nav model is
11	// one level deeper than the footer's: headerNavigation → items (1) → columns (2) → links (3)
12	// → link.regions (4). See footer/index.tsx's FOOTER_INCLUDE_DEPTH comment for what getting
13	// this wrong looks like (an under-resolved `regions` reference arrives as an unresolvable
14	// link stub with no `fields`, which throws when read).
15	const HEADER_NAV_INCLUDE_DEPTH = 4;
16	
17	const HEADER_NAV_QUERY_KEY = 'headerNavigation';
18	
19	type UseHeaderNavResult = {
20	  /** Region-resolved header nav items for the current storefront. `undefined` only while the
21	   *  fetch is in flight — once settled (success, error, or no entry for this region) this is
22	   *  always an array, empty if there's nothing to show, so a consumer's loading indicator
23	   *  doesn't spin forever waiting for a value that will never arrive. */
24	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
25	  isLoading: boolean;
26	  isError: boolean;
27	};
28	
29	// useMultiSite ships untyped from the base SFCC package — same cast FooterContainer already
30	// uses for this exact lookup.
31	type MultiSiteResult = { site: { id: string }; locale?: { id: string } };
32	
33	/**
34	 * Fetches the `headerNavigation` root entry from Contentful and resolves the region-scoped
35	 * entry for the current storefront, mirroring how `FooterContainer`
36	 * (overrides/app/components/footer/index.tsx) resolves `footerConfig` — same
37	 * `pickMostSpecificByRegion` root-resolution step, plus a `filterByRegion` pass over the
38	 * resolved entry's `items` array so each item's own `regions` field (per-item market
39	 * scoping, see headerNavItem.js) actually has an effect.
40	 *
41	 * Uses `@tanstack/react-query`'s `useQuery` rather than the footer's raw `useEffect`/
42	 * `useState` — the app already mounts a `QueryClientProvider` for every page via
43	 * `withReactQuery(AppConfig, ...)` in `_app-config`, so this needs no provider of its own.
44	 *
45	 * @returns the current storefront's resolved header nav items, plus query status flags.
46	 *   `items` is `undefined` while loading, on fetch failure, or when no entry resolves for
47	 *   this region — callers should treat that the same as "nothing to render yet," matching
48	 *   FooterContainer's "renders nothing" behaviour on an unresolved fetch.
49	 */
50	export const useHeaderNav = (): UseHeaderNavResult => {
51	  const { site, locale: siteLocale } = useMultiSite() as MultiSiteResult;
52	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
53	  const { client } = useContentfulClient();
54	
55	  const { data, isLoading, isError } = useQuery({
56	    queryKey: [HEADER_NAV_QUERY_KEY, site.id, locale],
57	    queryFn: async () => {
58	      // Guaranteed non-null: `enabled: !!client` below means this only runs once a client
59	      // exists, but TypeScript can't see that gate from inside the closure.
60	      // `useContentfulClient` types the client as `ContentfulClientApi<any>` for the
61	      // Experiences SDK's benefit — with `any` chain modifiers, `EntriesQueries`'s
62	      // `locale` field resolves out of the type entirely (see its `WITH_ALL_LOCALES`
63	      // conditional), so narrow back to the real default (`undefined`) modifiers here.
64	      const entries = await (client as ContentfulClientApi<undefined>)!.getEntries({
65	        content_type: CONTENT_TYPE_IDS.headerNavigation,
66	        include: HEADER_NAV_INCLUDE_DEPTH,
67	        locale,
68	      });
69	      // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
70	      // HeaderNavigationEntry mirrors the exact nested-resolved shape `include: 4`
71	      // produces for this content model.
72	      return entries.items as unknown as HeaderNavigationEntry[];
73	    },
74	    enabled: !!client,
75	  });
76	
77	  const resolved = data ? pickMostSpecificByRegion<HeaderNavigationEntry>(data, site.id) : undefined;
78	  const items = isLoading
79	    ? undefined
80	    : resolved
81	    ? filterByRegion<HeaderNavItemEntry>(resolved.fields.items, site.id)
82	    : [];
83	
84	  return { items, isLoading, isError };
85	};
