1	import { describe, test, expect, vi, beforeEach } from 'vitest';
2	import { waitFor } from '@testing-library/react';
3	import { renderHookWithQueryClient } from '../test-utils/renderWithProviders';
4	import { useHeaderNav } from './useHeaderNav';
5	import type { HeaderNavigationEntry, HeaderNavItemEntry, RegionEntry } from '../types/contentful';
6	
7	const mockGetEntries = vi.fn();
8	
9	vi.mock('./useContentfulClient', () => ({
10	  useContentfulClient: () => ({ client: { getEntries: mockGetEntries }, previewUnavailable: false, isPreview: false }),
11	}));
12	
13	let mockSiteId = 'ZimmermannAU';
14	let mockLocaleId: string | undefined = 'en-AU';
15	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
16	  default: () => ({ site: { id: mockSiteId }, locale: mockLocaleId ? { id: mockLocaleId } : undefined }),
17	}));
18	
19	const region = (siteId: string): RegionEntry => ({
20	  sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' } } },
21	  fields: { siteId, label: siteId },
22	});
23	
24	const navItem = (id: string, overrides: Partial<HeaderNavItemEntry['fields']> = {}): HeaderNavItemEntry => ({
25	  sys: { id, contentType: { sys: { id: 'headerNavItem' } } },
26	  fields: { label: id, ...overrides },
27	});
28	
29	const headerNav = (id: string, items: HeaderNavItemEntry[], regions?: RegionEntry[]): HeaderNavigationEntry => ({
30	  sys: { id, contentType: { sys: { id: 'headerNavigation' } } },
31	  fields: { internalTitle: id, items, regions },
32	});
33	
34	describe('useHeaderNav', () => {
35	  beforeEach(() => {
36	    vi.clearAllMocks();
37	    mockSiteId = 'ZimmermannAU';
38	    mockLocaleId = 'en-AU';
39	  });
40	
41	  test('resolves the most specific region-scoped headerNavigation entry over the global default', async () => {
42	    const globalItem = navItem('global-item');
43	    const auOnlyItem = navItem('au-item');
44	    const globalEntry = headerNav('global', [globalItem]);
45	    const auEntry = headerNav('au-scoped', [auOnlyItem], [region('ZimmermannAU')]);
46	
47	    mockGetEntries.mockResolvedValue({ items: [globalEntry, auEntry] });
48	
49	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
50	
51	    await waitFor(() => expect(result.current.isLoading).toBe(false));
52	
53	    expect(result.current.items).toEqual([auOnlyItem]);
54	  });
55	
56	  test("filters the resolved entry's items by each item's own regions field", async () => {
57	    const globalItem = navItem('global-item');
58	    const auItem = navItem('au-item', { regions: [region('ZimmermannAU')] });
59	    const usItem = navItem('us-item', { regions: [region('ZimmermannUS')] });
60	    const entry = headerNav('global', [globalItem, auItem, usItem]);
61	
62	    mockGetEntries.mockResolvedValue({ items: [entry] });
63	
64	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
65	
66	    await waitFor(() => expect(result.current.isLoading).toBe(false));
67	
68	    expect(result.current.items).toEqual([globalItem, auItem]);
69	  });
70	
71	  test('returns an empty array, not undefined, once settled with no entry eligible for the current region', async () => {
72	    // undefined must mean "still loading" only — a consumer's spinner (aria-busy tied to
73	    // isLoading) would otherwise spin forever once the fetch has actually settled.
74	    const usOnlyEntry = headerNav('us-scoped', [navItem('us-item')], [region('ZimmermannUS')]);
75	    mockGetEntries.mockResolvedValue({ items: [usOnlyEntry] });
76	
77	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
78	
79	    await waitFor(() => expect(result.current.isLoading).toBe(false));
80	
81	    expect(result.current.items).toEqual([]);
82	  });
83	
84	  test('passes the headerNavigation content type, include depth 4, and the active locale to the Contentful client', async () => {
85	    mockGetEntries.mockResolvedValue({ items: [] });
86	
87	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
88	
89	    await waitFor(() => expect(result.current.isLoading).toBe(false));
90	
91	    expect(mockGetEntries).toHaveBeenCalledWith({
92	      content_type: 'headerNavigation',
93	      include: 4,
94	      locale: 'en-AU',
95	    });
96	  });
97	
98	  test('falls back to the default Contentful locale when useMultiSite has no locale yet', async () => {
99	    mockLocaleId = undefined;
100	    mockGetEntries.mockResolvedValue({ items: [] });
101	
102	    const { result } = renderHookWithQueryClient(() => useHeaderNav());
103	
104	    await waitFor(() => expect(result.current.isLoading).toBe(false));
105	
106	    expect(mockGetEntries).toHaveBeenCalledWith(
107	      expect.objectContaining({ locale: 'en-US' })
108	    );
109	  });
110	});
