45	// Height derived from header.css.ts's logoBar padding, per design: logoBar is capped at
46	// 114px total (desktop/tablet) / 66px total (mobile), padding-bottom 48px/40px respectively,
47	// padding-top 0 — so logo height is 66px desktop/tablet, 26px mobile. Width is 'auto', not
48	// fixed, so it follows the wordmark's native aspect ratio at that height (no distortion, no
49	// letterboxing). Set here rather than in header.css.ts's `Header` recipe: Chakra's multi-part
50	// recipe merge silently loses an override to base SFCC's own `logo` part here.
51	// audit-allow: literal design-spec value, no named token exists for it.
52	const HEADER_LOGO_SX: SystemStyleObject = {
53	  // Overrides ZimmLogo's own maxWidth: 327px default, which would otherwise cap this.
54	  maxWidth: 'none',
55	  width: 'auto',
56	  height: { base: '26px', sm: '26px', md: '74px', lg: '74px', xl: '74px', '2xl': '74px' },
57	};
58	
59	// Outer horizontal padding, sourced from the shared --zimm-grid-margin-*/--zimm-grid-max-width
60	// tokens (gridSystem.ts) rather than hardcoded here — same values apply to footer and the
61	// main content area, one place to change all three. Set directly on this div rather than
62	// through header.css.ts's `Header` recipe, for the same reason as HEADER_LOGO_SX above:
63	// Chakra's multi-part recipe merge doesn't reliably let an override win against base SFCC's
64	// own `content` part here.
65	const HEADER_CONTENT_SX: SystemStyleObject = {
66	  maxWidth: 'var(--zimm-grid-max-width)',
67	  marginLeft: 0,
68	  marginRight: 0,
69	  paddingTop: 0,
70	  paddingBottom: 0,
71	  paddingLeft: {
72	    base: 'var(--zimm-grid-margin-mobile)',
73	    sm: 'var(--zimm-grid-margin-mobile)',
74	    md: 'var(--zimm-grid-margin-tablet)',
75	    lg: 'var(--zimm-grid-margin-tablet)',
76	    xl: 'var(--zimm-grid-margin-desktop)',
77	    '2xl': 'var(--zimm-grid-margin-desktop)',
78	  },
79	  paddingRight: {
80	    base: 'var(--zimm-grid-margin-mobile)',
81	    sm: 'var(--zimm-grid-margin-mobile)',
82	    md: 'var(--zimm-grid-margin-tablet)',
83	    lg: 'var(--zimm-grid-margin-tablet)',
84	    xl: 'var(--zimm-grid-margin-desktop)',
85	    '2xl': 'var(--zimm-grid-margin-desktop)',
86	  },
87	};
