1	import { useCallback, useMemo, useRef, useState } from 'react';
2	import type { HeaderNavItemEntry } from 'app/types/contentful';
3	import type { MenuExpandedState } from 'app/components/header/headerTypes';
4	import type { DrawerMenuStateContextValue } from './useDrawerMenuState';
5	
6	type MobileDepth = 'closed' | 'L1' | 'L2';
7	
8	export type HeaderMenuExpandedController = {
9	  /** Value to pass straight through to LeftBar/RightBar's `menuExpanded` prop. */
10	  menuExpanded: MenuExpandedState;
11	  /** Wire to LeftBar's `onMenuClick` — opens the L1 drawer when closed, closes it when open
12	   * (toggle semantics; see leftBar/index.tsx's own JSDoc on this contract). */
13	  handleMenuClick: () => void;
14	  /** Wire to LeftBar's `onBack` — returns from L2 to L1 without closing the drawer. */
15	  handleBack: () => void;
16	  /** Wire to RightBar's `onClose` — closes the drawer entirely from `fullSwap`/`mobileL2`. */
17	  handleClose: () => void;
18	  /** Provide via `DrawerMenuStateContext.Provider` around `children` so the nested DrawerMenu
19	   * (see useDrawerMenuState.ts) can read/report L1↔L2 state. */
20	  contextValue: DrawerMenuStateContextValue;
21	};
22	
23	/**
24	 * Owns the header shell's mobile drawer open/depth state and derives the `menuExpanded` value
25	 * LeftBar/RightBar need (see header/headerTypes.ts). Extracted out of header/index.tsx to keep
26	 * that file under the complexity guideline in .claude/rules/components.md — this is plain
27	 * open/closed/depth state, not async, so a handful of useState/useCallback is enough (no
28	 * reducer or state library needed).
29	 *
30	 * Header has no `onClose` prop of its own: base `_app`'s `useDisclosure` only ever passes
31	 * `onMenuClick={onOpen}` to `<Header>` and `isOpen`/`onClose` directly to the sibling
32	 * `<DrawerMenu>` it renders as Header's `children` — see header/index.tsx's own comment on
33	 * this exact gap. Closing the drawer from LeftBar's 'X' or RightBar's close icon therefore
34	 * goes through `registerCloseHandler` instead: DrawerMenu registers its real `onClose` once
35	 * mounted (via the Context this hook's `contextValue` provides), and `handleMenuClick`/
36	 * `handleClose` below call that registered function to actually close the physical Drawer.
37	 *
38	 * @param onMenuClick the real `onMenuClick` prop Header received from base `_app` (its
39	 *   `onOpen`) — called only when the drawer is currently closed, since `onOpen` cannot toggle.
40	 * @returns `menuExpanded` plus the click handlers and Context value described above.
41	 */
42	export const useHeaderMenuExpandedState = (onMenuClick: () => void): HeaderMenuExpandedController => {
43	  const [depth, setDepth] = useState<MobileDepth>('closed');
44	  const [activeItem, setActiveItem] = useState<HeaderNavItemEntry | null>(null);
45	  const closeHandlerRef = useRef<(() => void) | null>(null);
46	
47	  const menuExpanded: MenuExpandedState = depth === 'closed' ? 'closed' : depth === 'L1' ? 'mobileL1' : 'mobileL2';
48	
49	  const resetToClosed = useCallback(() => {
50	    setDepth('closed');
51	    setActiveItem(null);
52	  }, []);
53	
54	  const handleMenuClick = useCallback(() => {
55	    if (depth === 'closed') {
56	      onMenuClick();
57	      setDepth('L1');
58	    } else {
59	      closeHandlerRef.current?.();
60	      resetToClosed();
61	    }
62	  }, [depth, onMenuClick, resetToClosed]);
63	
64	  const handleBack = useCallback(() => {
65	    setDepth('L1');
66	    setActiveItem(null);
67	  }, []);
68	
69	  const handleClose = useCallback(() => {
70	    closeHandlerRef.current?.();
71	    resetToClosed();
72	  }, [resetToClosed]);
73	
74	  const drillInto = useCallback((item: HeaderNavItemEntry) => {
75	    setDepth('L2');
76	    setActiveItem(item);
77	  }, []);
78	
79	  const registerCloseHandler = useCallback((fn: (() => void) | null) => {
80	    closeHandlerRef.current = fn;
81	  }, []);
82	
83	  const contextValue = useMemo<DrawerMenuStateContextValue>(
84	    () => ({
85	      activeItem,
86	      isDrilledIn: depth === 'L2',
87	      drillInto,
88	      notifyClosed: resetToClosed,
89	      registerCloseHandler,
90	    }),
91	    [activeItem, depth, drillInto, resetToClosed, registerCloseHandler],
92	  );
93	
94	  return { menuExpanded, handleMenuClick, handleBack, handleClose, contextValue };
95	};
