1	import type { HeaderNavItemEntry, NavGroupEntry } from 'app/types/contentful';
2	import { resolveImageEntry } from 'app/utils/resolveImageEntry';
3	import type { MegaMenuItem, MegaMenuSection } from './types';
4	
5	/** `ListMenuPopover`/base `ListMenuContent` share a generic `item[itemsKey]` contract —
6	 *  `itemsKey` is always `'columns'` for a `headerNavItem` in practice, but arrives as a plain
7	 *  string to match that contract rather than a hardcoded literal. */
8	type FieldsWithSections = Record<string, ReadonlyArray<NavGroupEntry> | undefined> & {
9	  twoColumnLayout?: boolean;
10	};
11	
12	const toSection = (group: NavGroupEntry): MegaMenuSection => {
13	  // An empty/whitespace-only heading is Contentful's "unheaded group" shape (the curated
14	  // groups seen under "New" have no heading) — treated the same as an omitted heading, not
15	  // rendered as a blank heading element.
16	  const heading = group.fields.heading?.trim();
17	
18	  return {
19	    heading: heading ? heading : undefined,
20	    links: group.fields.links.map((link) => ({
21	      label: link.fields.label,
22	      href: link.fields.href,
23	    })),
24	  };
25	};
26	
27	/**
28	 * Isolates all knowledge of the raw `headerNavItem`/`navGroup`/`link`/asset Contentful shape
29	 * behind one adapter, so `megaMenuContent`'s presentational component only ever deals with
30	 * `MegaMenuItem`.
31	 *
32	 * @param item the raw `headerNavItem` entry
33	 * @param itemsKey the field name holding this item's mega-menu columns
34	 * @returns the item's sections plus an optional promo image, in the component's own shape
35	 */
36	export const toMegaMenuItem = (item: HeaderNavItemEntry, itemsKey: string): MegaMenuItem => {
37	  // Cast is unavoidable: itemsKey is a plain string (matching ListMenuPopover's generic
38	  // contract), so TypeScript can't narrow `item.fields`'s literal key type from it.
39	  const itemFields = item.fields as unknown as FieldsWithSections;
40	  const sectionsField = itemFields[itemsKey] ?? [];
41	  const sections = sectionsField.map(toSection);
42	
43	  // Default: every group stacks in one shared column (confirmed via Figma's "New" frame).
44	  // twoColumnLayout splits them into two side-by-side columns instead — an explicit editorial
45	  // flag rather than inferring column count from heading presence or group count. Guarded by
46	  // sections.length > 1: a single-section group with twoColumnLayout set would otherwise split
47	  // into [[section], []] — a real column with content plus an empty one that still renders
48	  // (and still gets two-column link styling applied to the only section present).
49	  const columns = itemFields.twoColumnLayout && sections.length > 1 ? splitEvenly(sections, 2) : [sections];
50	
51	  const promoImage = resolveImageEntry(item.fields.promoImage);
52	
53	  return { columns, promoImage };
54	};
55	
56	/** Splits `items` into `columnCount` columns as evenly as possible, preserving order — the
57	 *  first column gets the larger half when the count is odd. */
58	const splitEvenly = <T>(items: T[], columnCount: number): T[][] => {
59	  const perColumn = Math.ceil(items.length / columnCount);
60	  return Array.from({ length: columnCount }, (_, i) => items.slice(i * perColumn, (i + 1) * perColumn));
61	};
